PRAGMA foreign_keys = ON;
CREATE TABLE workspaces(id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')),timezone TEXT NOT NULL DEFAULT 'Asia/Kuala_Lumpur',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,password_hash TEXT NOT NULL,is_platform_admin INTEGER NOT NULL DEFAULT 0,is_active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE memberships(workspace_id TEXT NOT NULL,user_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('qa','manager','worker')),is_active INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(workspace_id,user_id),FOREIGN KEY(workspace_id) REFERENCES workspaces(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires_at INTEGER NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE login_limits(key TEXT PRIMARY KEY,attempts INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE label_sizes(id TEXT NOT NULL,workspace_id TEXT NOT NULL,code TEXT NOT NULL,width_mm REAL NOT NULL CHECK(width_mm>0 AND width_mm<=300),height_mm REAL NOT NULL CHECK(height_mm>0 AND height_mm<=300),gap_mm REAL NOT NULL DEFAULT 2,dpi INTEGER NOT NULL DEFAULT 300 CHECK(dpi IN (203,300)),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,code),FOREIGN KEY(workspace_id) REFERENCES workspaces(id));
CREATE TABLE templates(id TEXT NOT NULL,workspace_id TEXT NOT NULL,name TEXT NOT NULL,design_json TEXT NOT NULL,size_id TEXT,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')),version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,size_id) REFERENCES label_sizes(workspace_id,id));
CREATE TABLE template_versions(workspace_id TEXT NOT NULL,template_id TEXT NOT NULL,version INTEGER NOT NULL,design_json TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,template_id,version),FOREIGN KEY(workspace_id,template_id) REFERENCES templates(workspace_id,id));
CREATE TABLE skus(id TEXT NOT NULL,workspace_id TEXT NOT NULL,sku_code TEXT NOT NULL,name TEXT NOT NULL,name_en TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT '',spec TEXT NOT NULL DEFAULT '',barcode TEXT NOT NULL DEFAULT '',weight TEXT NOT NULL DEFAULT '',size_code TEXT NOT NULL DEFAULT '',expiry_days INTEGER CHECK(expiry_days>=0),image_key TEXT,extra TEXT NOT NULL DEFAULT '{}',is_active INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL,PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,sku_code),FOREIGN KEY(workspace_id) REFERENCES workspaces(id));
CREATE INDEX skus_filter ON skus(workspace_id,is_active,sku_code);
CREATE INDEX skus_category ON skus(workspace_id,category);
CREATE INDEX skus_size ON skus(workspace_id,size_code);
CREATE TABLE mappings(id TEXT NOT NULL,workspace_id TEXT NOT NULL,name TEXT NOT NULL,config_json TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')),updated_at TEXT NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id) REFERENCES workspaces(id));
CREATE TABLE mapping_versions(workspace_id TEXT NOT NULL,mapping_id TEXT NOT NULL,version INTEGER NOT NULL,config_json TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,mapping_id,version),FOREIGN KEY(workspace_id,mapping_id) REFERENCES mappings(workspace_id,id));
CREATE TABLE template_rules(id TEXT NOT NULL,workspace_id TEXT NOT NULL,template_id TEXT NOT NULL,priority INTEGER NOT NULL,match_category TEXT,match_size_code TEXT,match_sku_prefix TEXT,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,template_id) REFERENCES templates(workspace_id,id));
CREATE INDEX rules_priority ON template_rules(workspace_id,priority,id);
CREATE TABLE assets(id TEXT NOT NULL,workspace_id TEXT NOT NULL,filename TEXT NOT NULL,r2_key TEXT NOT NULL UNIQUE,file_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id) REFERENCES workspaces(id));
CREATE TABLE imports(id TEXT NOT NULL,workspace_id TEXT NOT NULL,rows_json TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('review','applied')),base_hash TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,id));
CREATE TABLE print_jobs(id TEXT NOT NULL,workspace_id TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'labels' CHECK(kind IN ('labels','export')),status TEXT NOT NULL CHECK(status IN ('review','pending','processing','completed','failed','cancelled')),input_hash TEXT NOT NULL,idempotency_key TEXT NOT NULL,output_type TEXT NOT NULL CHECK(output_type IN ('pdf','zpl','both','zip')),total_count INTEGER NOT NULL DEFAULT 0,success_count INTEGER NOT NULL DEFAULT 0,result_r2_keys TEXT NOT NULL DEFAULT '[]',error_message TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,finished_at TEXT,PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,idempotency_key));
CREATE TABLE print_job_items(workspace_id TEXT NOT NULL,job_id TEXT NOT NULL,position INTEGER NOT NULL,sku_id TEXT NOT NULL,copies INTEGER NOT NULL CHECK(copies>0),snapshot_json TEXT NOT NULL,PRIMARY KEY(workspace_id,job_id,position),FOREIGN KEY(workspace_id,job_id) REFERENCES print_jobs(workspace_id,id));
CREATE TABLE job_parts(workspace_id TEXT NOT NULL,job_id TEXT NOT NULL,part INTEGER NOT NULL,labels INTEGER NOT NULL,keys_json TEXT NOT NULL,PRIMARY KEY(workspace_id,job_id,part),FOREIGN KEY(workspace_id,job_id) REFERENCES print_jobs(workspace_id,id));
CREATE TABLE print_records(id TEXT NOT NULL,workspace_id TEXT NOT NULL,job_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('original','reprint','test','waste')),quantity INTEGER NOT NULL CHECK(quantity>0),printer_name TEXT NOT NULL,note TEXT NOT NULL,operator_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,idempotency_key),FOREIGN KEY(workspace_id,job_id) REFERENCES print_jobs(workspace_id,id));
CREATE INDEX records_forecast ON print_records(workspace_id,created_at,kind);
CREATE TABLE audit_events(id TEXT PRIMARY KEY,workspace_id TEXT,user_id TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,created_at TEXT NOT NULL,detail_json TEXT NOT NULL DEFAULT '{}');
CREATE INDEX audit_workspace ON audit_events(workspace_id,created_at);
CREATE TABLE mutation_checks(id TEXT PRIMARY KEY,actual INTEGER NOT NULL,expected INTEGER NOT NULL,CHECK(actual=expected));
CREATE TRIGGER original_print_limit BEFORE INSERT ON print_records WHEN NEW.kind='original'
BEGIN
 SELECT CASE WHEN COALESCE((SELECT SUM(quantity) FROM print_records WHERE workspace_id=NEW.workspace_id AND job_id=NEW.job_id AND kind='original'),0)+NEW.quantity>(SELECT total_count FROM print_jobs WHERE workspace_id=NEW.workspace_id AND id=NEW.job_id) THEN RAISE(ABORT,'original confirmation exceeds generated quantity') END;
END;
